const queryClient = new QueryClient();
type IconType = ComponentType<{ size?: number; strokeWidth?: number; className?: string }>;

function Avatar({ name, image, size = 'md', verified = false }: { name: string; image?: string; size?: 'sm' | 'md' | 'lg' | 'xl'; verified?: boolean }) {
  const sizes = { sm: 'h-8 w-8 text-[10px]', md: 'h-10 w-10 text-[11px]', lg: 'h-14 w-14 text-base', xl: 'h-20 w-20 text-xl' };
  const initials = name.split(' ').map((word) => word[0]).slice(0, 2).join('').toUpperCase();
  return <span className={`relative inline-flex shrink-0 items-center justify-center overflow-visible rounded-full bg-[hsl(var(--primary))] font-bold text-white ${sizes[size]}`}>
    {image ? <img src={image} alt="" className="relative h-full w-full rounded-full object-cover" /> : <span>{initials}</span>}
    {verified && <BadgeCheck size={size === 'sm' ? 12 : 15} className="absolute -bottom-0.5 -right-1 rounded-full bg-[hsl(var(--card))] text-[hsl(var(--primary))]" />}
  </span>;
}

function LoadingBlock({ lines = 3 }: { lines?: number }) {
  return <div className="space-y-3 animate-pulse" data-testid="loading-state">{Array.from({ length: lines }).map((_, index) => <div key={index} className={`h-3 rounded-full bg-[hsl(var(--muted))] ${index === lines - 1 ? 'w-2/3' : 'w-full'}`} />)}</div>;
}

function QueryError({ onRetry, label = 'The academic network is taking a moment.' }: { onRetry: () => void; label?: string }) {
  return <div className="card-lumen rounded-2xl border hairline p-8 text-center" data-testid="status-error">
    <div className="mx-auto mb-3 flex h-10 w-10 items-center justify-center rounded-full bg-[hsl(var(--destructive)/.12)] text-[hsl(var(--destructive))]"><RefreshCw size={18} /></div>
    <p className="text-sm font-semibold">{label}</p><p className="mt-1 text-xs text-muted-foreground">Try again in a moment.</p>
    <button onClick={onRetry} data-testid="button-retry" className="mt-5 inline-flex items-center gap-2 rounded-xl border px-4 py-2 text-xs font-bold transition hover:border-[hsl(var(--primary))] hover:bg-[hsl(var(--muted))]"><RefreshCw size={13} /> Try again</button>
  </div>;
}

function EmptyState({ icon: Icon, title, copy, action }: { icon: IconType; title: string; copy: string; action?: ReactNode }) {
  return <div className="card-lumen rounded-2xl border hairline px-7 py-14 text-center" data-testid="empty-state">
    <div className="mx-auto mb-4 flex h-12 w-12 items-center justify-center rounded-2xl bg-[hsl(var(--primary)/.13)] text-[hsl(var(--primary))]"><Icon size={22} /></div>
    <h3 className="text-xl font-bold tracking-tight">{title}</h3><p className="mx-auto mt-2 max-w-sm text-sm leading-6 text-muted-foreground">{copy}</p>{action}
  </div>;
}

const navItems = [
  { href: '/', label: 'Home', icon: Sparkles },
  { href: '/explore', label: 'Explore', icon: Compass },
  { href: '/shorts', label: 'Shorts', icon: PlaySquare },
  { href: '/campus', label: 'Campus', icon: Landmark },
  { href: '/courses', label: 'Courses', icon: GraduationCap },
  { href: '/communities', label: 'Communities', icon: Users },
  { href: '/library', label: 'Library', icon: LibraryBig },
  { href: '/events', label: 'Events', icon: CalendarDays },
  { href: '/ai', label: 'Lumen AI', icon: Bot },
  { href: '/chat', label: 'Messages', icon: MessageCircle },
];

function Sidebar({ profile, location, onClose }: { profile: any; location: string; onClose?: () => void }) {
  return <aside className="flex h-full w-[252px] shrink-0 flex-col border-r border-[hsl(var(--sidebar-border))] bg-[hsl(var(--sidebar))] px-4 py-5 text-[hsl(var(--sidebar-foreground))]" data-testid="navigation-sidebar">
    <div className="flex items-center justify-between px-3"><Link href="/" onClick={onClose} className="flex items-center gap-2.5" data-testid="link-logo">
      <span className="flex h-9 w-9 items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-white"><Sparkles size={17} /></span><span className="text-[17px] font-extrabold tracking-[-.05em]">lumen<span className="text-[hsl(var(--accent))]">univ</span></span>
    </Link>{onClose && <button onClick={onClose} aria-label="Close menu" data-testid="button-close-menu" className="rounded-lg p-2 hover:bg-white/10"><X size={18} /></button>}</div>
    <div className="mt-10 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-white/40">Your academic desk</div>
    <nav className="mt-3 space-y-1" aria-label="Primary navigation">{navItems.map(({ href, label, icon: Icon }) => {
      const active = href === '/' ? location === '/' : location.startsWith(href);
      return <Link key={href} href={href} onClick={onClose} data-testid={`link-nav-${label.toLowerCase()}`} className={`group flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-semibold transition ${active ? 'bg-[hsl(var(--primary))] text-white shadow-[0_10px_26px_-16px_hsl(var(--primary))]' : 'text-white/62 hover:bg-white/[.07] hover:text-white'}`}><Icon size={17} /><span>{label}</span>{label === 'Messages' && <span className="ml-auto rounded-full bg-[hsl(var(--accent))] px-1.5 py-0.5 text-[9px] font-extrabold text-[hsl(var(--accent-foreground))]">3</span>}</Link>;
    })}</nav>
    <div className="mt-8 border-t border-white/10 pt-5"><div className="px-3 text-[10px] font-bold uppercase tracking-[.18em] text-white/35">Your space</div>
      <Link href="/profile" onClick={onClose} data-testid="link-nav-profile" className="mt-3 flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-semibold text-white/62 hover:bg-white/[.07] hover:text-white"><UserRound size={17} /> Profile</Link>
      <Link href="/settings" onClick={onClose} data-testid="link-settings" className="flex items-center gap-3 rounded-xl px-3 py-2.5 text-[13px] font-semibold text-white/62 hover:bg-white/[.07] hover:text-white"><Settings size={17} /> Settings</Link>
    </div>
    <div className="mt-auto"><Link href="/profile" onClick={onClose} data-testid="link-profile-card" className="flex items-center gap-3 rounded-2xl border border-white/10 bg-white/[.04] p-3 hover:bg-white/[.08]">
      <Avatar name={profile?.name ?? 'Academic profile'} image={profile?.avatar} size="sm" verified={profile?.verified} /><span className="min-w-0 flex-1"><span className="block truncate text-xs font-bold">{profile?.name ?? 'Your profile'}</span><span className="mt-0.5 block truncate text-[10px] text-white/45">{profile?.handle ? `@${profile.handle}` : 'Set up your identity'}</span></span><ChevronRight size={14} className="text-white/35" />
    </Link><p className="mt-4 px-3 text-[10px] leading-5 text-white/35">Learn. Connect. Discover.</p></div>
  </aside>;
}

function Topbar({ profile, searchValue, setSearchValue, onMenu }: { profile: any; searchValue: string; setSearchValue: (value: string) => void; onMenu: () => void }) {
  const [, setLocation] = useLocation();
  return <header className="sticky top-0 z-20 flex h-[72px] items-center justify-between border-b border-[hsl(var(--border)/.8)] bg-[hsl(var(--background)/.9)] px-4 backdrop-blur-xl md:px-8" data-testid="topbar">
    <button onClick={onMenu} className="mr-3 rounded-lg p-2 text-muted-foreground md:hidden" aria-label="Open menu" data-testid="button-open-menu"><Menu size={20} /></button>
    <div className="relative hidden max-w-[430px] flex-1 md:block"><Search size={16} className="absolute left-3.5 top-3.5 text-muted-foreground" /><input value={searchValue} onChange={(event) => setSearchValue(event.target.value)} onKeyDown={(event) => { if (event.key === 'Enter') setLocation('/explore'); }} placeholder="Search people, universities, fields" data-testid="input-global-search" className="h-11 w-full rounded-xl border bg-[hsl(var(--card)/.72)] pl-10 pr-4 text-xs font-medium outline-none transition placeholder:text-muted-foreground/80 focus:border-[hsl(var(--primary))] focus:ring-2 focus:ring-[hsl(var(--primary)/.16)]" /></div>
    <div className="ml-auto flex items-center gap-1.5"><button onClick={() => setLocation('/explore')} data-testid="button-mobile-search" aria-label="Search" className="rounded-xl p-2.5 text-muted-foreground hover:bg-[hsl(var(--muted))] md:hidden"><Search size={18} /></button>
      <Link href="/settings" data-testid="link-notifications" aria-label="Notifications" className="relative rounded-xl p-2.5 text-muted-foreground transition hover:bg-[hsl(var(--muted))] hover:text-foreground"><Bell size={18} /><span className="absolute right-2 top-2 h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent))]" /></Link>
      <Link href="/profile" data-testid="link-top-profile" className="hidden items-center gap-2 border-l pl-3 sm:flex"><Avatar name={profile?.name ?? 'Profile'} image={profile?.avatar} size="sm" verified={profile?.verified} /><span className="max-w-[125px] truncate text-xs font-bold">{profile?.name ?? 'Academic profile'}</span></Link>
    </div>
  </header>;
}

function MobileNav({ onCreate }: { onCreate: () => void }) {
  const [location] = useLocation();
  return <nav className="fixed inset-x-0 bottom-0 z-30 grid h-[72px] grid-cols-5 border-t bg-[hsl(var(--card)/.96)] px-3 pb-[env(safe-area-inset-bottom)] shadow-[0_-8px_28px_hsl(225_38%_10%/.08)] backdrop-blur-xl md:hidden" aria-label="Mobile navigation">
    <Link href="/" data-testid="mobile-nav-home" className={`flex flex-col items-center justify-center gap-1 text-[10px] font-semibold ${location === '/' ? 'text-[hsl(var(--primary))]' : 'text-muted-foreground'}`}><Sparkles size={19} />Home</Link>
    <Link href="/explore" data-testid="mobile-nav-explore" className={`flex flex-col items-center justify-center gap-1 text-[10px] font-semibold ${location.startsWith('/explore') ? 'text-[hsl(var(--primary))]' : 'text-muted-foreground'}`}><Compass size={19} />Explore</Link>
    <button onClick={onCreate} data-testid="button-mobile-create" aria-label="Create a post" className="relative -top-5 mx-auto flex h-14 w-14 flex-col items-center justify-center gap-0.5 rounded-full border-4 border-[hsl(var(--background))] bg-[hsl(var(--primary))] text-white shadow-[0_8px_24px_hsl(var(--primary)/.32)]"><Plus size={24} /><span className="text-[9px] font-bold">Create</span></button>
    <Link href="/chat" data-testid="mobile-nav-chat" className={`flex flex-col items-center justify-center gap-1 text-[10px] font-semibold ${location.startsWith('/chat') ? 'text-[hsl(var(--primary))]' : 'text-muted-foreground'}`}><MessageCircle size={19} />Messages</Link>
    <Link href="/profile" data-testid="mobile-nav-profile" className={`flex flex-col items-center justify-center gap-1 text-[10px] font-semibold ${location.startsWith('/profile') ? 'text-[hsl(var(--primary))]' : 'text-muted-foreground'}`}><UserRound size={19} />Profile</Link>
  </nav>;
}

function CreateSheet({ open, onClose, profile, onPublished }: { open: boolean; onClose: () => void; profile: any; onPublished: () => void }) {
  if (!open) return null;
  return <div className="fixed inset-0 z-50 flex items-end justify-center bg-[hsl(225_48%_4%/.5)] p-0 md:items-center md:p-4" role="dialog" aria-modal="true" aria-label="Create a post">
    <div className="card-lumen w-full max-w-lg rounded-t-3xl border p-5 md:rounded-3xl md:p-6"><div className="mb-5 flex items-center justify-between"><div><p className="mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--primary))]">Create</p><h2 className="mt-1 text-xl font-bold">Share with your campus</h2></div><button onClick={onClose} aria-label="Close create dialog" data-testid="button-close-create" className="rounded-xl p-2 text-muted-foreground hover:bg-[hsl(var(--muted))]"><X size={18} /></button></div><Composer profile={profile} onPublished={() => { onPublished(); onClose(); }} compact /></div>
  </div>;
}

function Composer({ profile, onPublished, compact = false }: { profile: any; onPublished: () => void; compact?: boolean }) {
  const [body, setBody] = useState(''); const [topic, setTopic] = useState(''); const createPost = useCreatePost(); const client = useQueryClient();
  const submit = () => { if (!body.trim() || createPost.isPending) return; createPost.mutate({ data: { body: body.trim(), topic: topic.trim() || null, image: null } }, { onSuccess: () => { setBody(''); setTopic(''); client.invalidateQueries({ queryKey: getListFeedPostsQueryKey() }); onPublished(); } }); };
  return <section className={`card-lumen rounded-2xl border hairline ${compact ? 'p-0 border-0 shadow-none' : 'p-4 sm:p-5'}`} data-testid="composer"><div className="flex gap-3"><Avatar name={profile?.name ?? 'You'} image={profile?.avatar} size="md" verified={profile?.verified} /><div className="min-w-0 flex-1"><textarea value={body} onChange={(event) => setBody(event.target.value)} data-testid="input-post-body" placeholder="What are you learning, making, or questioning?" maxLength={1000} rows={compact ? 5 : 3} className="w-full resize-none bg-transparent pt-1 text-sm leading-6 outline-none placeholder:text-muted-foreground" /><div className="flex flex-wrap items-center justify-between gap-3 border-t pt-3"><div className="flex items-center gap-1"><button type="button" onClick={() => setBody((value) => `${value}${value ? ' ' : ''}[Media]`)} data-testid="button-add-image" className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-[11px] font-bold text-muted-foreground hover:bg-[hsl(var(--muted))]"><ImageIcon size={14} /> Media</button><button type="button" onClick={() => setTopic(topic ? '' : 'Research note')} data-testid="button-add-topic" className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-[11px] font-bold text-muted-foreground hover:bg-[hsl(var(--muted))]"><Plus size={14} /> Topic</button>{topic && <input value={topic} onChange={(event) => setTopic(event.target.value)} placeholder="Topic label" data-testid="input-post-topic" className="h-7 w-28 rounded-md border bg-transparent px-2 text-[11px] outline-none focus:border-[hsl(var(--primary))]" />}</div><div className="flex items-center gap-3"><span className="mono text-[10px] text-muted-foreground">{body.length}/1000</span><button type="button" onClick={submit} disabled={!body.trim() || createPost.isPending} data-testid="button-publish-post" className="inline-flex items-center gap-2 rounded-lg bg-[hsl(var(--primary))] px-3.5 py-2 text-xs font-extrabold text-white transition hover:brightness-95 disabled:cursor-not-allowed disabled:opacity-45">{createPost.isPending ? 'Publishing…' : 'Publish'} <Send size={13} /></button></div></div></div></div></section>;
}

function PostCard({ post, onLike }: { post: any; onLike: (id: string) => void }) {
  const [feedback, setFeedback] = useState(''); const [menuOpen, setMenuOpen] = useState(false);
  return <article className="card-lumen rounded-2xl border hairline p-4 transition hover:-translate-y-0.5 hover:shadow-[var(--shadow-md)] sm:p-5" data-testid={`card-post-${post.id}`}><div className="flex items-start gap-3"><Avatar name={post.author?.name ?? 'Academic contributor'} image={post.author?.avatar} size="md" verified={post.author?.verified} /><div className="min-w-0 flex-1"><div className="flex items-center gap-2"><span className="truncate text-sm font-extrabold">{post.author?.name ?? 'Academic contributor'}</span>{post.author?.role && <span className="hidden rounded-full bg-[hsl(var(--muted))] px-2 py-0.5 text-[9px] font-bold text-muted-foreground sm:inline">{post.author.role}</span>}<button aria-label="Post options" onClick={() => setMenuOpen((value) => !value)} data-testid={`button-post-menu-${post.id}`} className="ml-auto rounded-lg p-1 text-muted-foreground hover:bg-[hsl(var(--muted))]"><MoreHorizontal size={17} /></button></div><div className="mt-0.5 flex flex-wrap gap-x-2 text-[11px] text-muted-foreground"><span>@{post.author?.handle ?? 'academic'}</span><span>·</span><span>{formatWhen(post.publishedAt)}</span>{post.university && <><span>·</span><span>{post.university}</span></>}</div>{menuOpen && <div className="mt-2 rounded-lg border bg-[hsl(var(--muted)/.5)] px-3 py-2 text-[10px] font-semibold text-muted-foreground">Post controls are available when moderation is connected.</div>}</div></div><p className="mt-4 whitespace-pre-line text-[14px] leading-7 text-[hsl(var(--foreground)/.9)]">{post.body}</p>{post.topic && <div className="mt-4 inline-flex items-center gap-1.5 rounded-full border border-[hsl(var(--primary)/.3)] bg-[hsl(var(--primary)/.1)] px-2.5 py-1 text-[10px] font-bold"><span className="text-[hsl(var(--primary))]">#</span>{post.topic}</div>}{post.image && <img src={post.image} alt="" className="mt-4 max-h-80 w-full rounded-xl object-cover" />}<div className="mt-5 flex items-center gap-1 border-t pt-3"><button onClick={() => onLike(post.id)} data-testid={`button-like-${post.id}`} aria-label={post.liked ? 'Unlike post' : 'Like post'} className={`group inline-flex items-center gap-2 rounded-lg px-2.5 py-2 text-xs font-bold transition hover:bg-[hsl(var(--muted))] ${post.liked ? 'text-[hsl(var(--primary))]' : 'text-muted-foreground'}`}><Heart size={16} className={post.liked ? 'fill-[hsl(var(--primary))]' : 'transition group-hover:scale-110'} /> {post.likes}</button><button onClick={() => setFeedback('Comments will open when the discussion API is connected.')} data-testid={`button-comment-${post.id}`} className="inline-flex items-center gap-2 rounded-lg px-2.5 py-2 text-xs font-bold text-muted-foreground hover:bg-[hsl(var(--muted))]"><MessageSquare size={16} /> {post.comments}</button><button onClick={() => setFeedback('Repost is a preview action until sharing is connected.')} data-testid={`button-repost-${post.id}`} className="inline-flex items-center gap-2 rounded-lg px-2.5 py-2 text-xs font-bold text-muted-foreground hover:bg-[hsl(var(--muted))]"><Repeat2 size={16} /> {post.reposts}</button><button onClick={() => setFeedback('Link sharing will be available soon.')} data-testid={`button-share-${post.id}`} aria-label="Share post" className="ml-auto rounded-lg p-2 text-muted-foreground hover:bg-[hsl(var(--muted))]"><ExternalLink size={15} /></button></div>{feedback && <p className="mt-2 rounded-lg bg-[hsl(var(--muted)/.65)] px-3 py-2 text-[10px] font-semibold text-muted-foreground">{feedback}</p>}</article>;
}

function Stories({ profile }: { profile: any }) {
  const names = [profile?.name ?? 'Your story', 'Ama Mensah', 'Koffi Adjei', 'Sarah Chen', 'Marie Diallo']; const [active, setActive] = useState<number | null>(null);
  return <section className="card-lumen rounded-2xl border hairline p-4" data-testid="stories-row"><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-extrabold">Campus moments</h2><span className="mono text-[10px] text-muted-foreground">{active === null ? '24H' : 'SELECTED'}</span></div><div className="lumen-scrollbar flex gap-4 overflow-x-auto pb-1">{names.map((name, index) => <button key={name} onClick={() => setActive(index)} data-testid={`button-story-${index}`} className="flex w-[58px] shrink-0 flex-col items-center gap-2 text-center"><span className={`rounded-full p-[2px] ${active === index ? 'bg-[hsl(var(--accent))]' : index === 0 ? 'bg-[hsl(var(--muted))]' : 'bg-[linear-gradient(135deg,hsl(var(--primary)),hsl(var(--accent)))]'}`}><Avatar name={name} image={index === 0 ? profile?.avatar : undefined} size="lg" /></span><span className="w-full truncate text-[10px] font-semibold">{index === 0 ? 'Your story' : name.split(' ')[0]}</span></button>)}</div></section>;
}

function SummaryRail({ summary, communities }: { summary: any; communities: any[] }) {
  return <aside className="space-y-4 xl:sticky xl:top-24 xl:self-start"><section className="relative overflow-hidden rounded-2xl bg-[hsl(var(--sidebar))] p-5 text-[hsl(var(--sidebar-foreground))]" data-testid="card-next-class"><div className="lumen-grid absolute inset-0 opacity-20" /><div className="relative"><div className="mono text-[10px] uppercase tracking-[.18em] text-[hsl(var(--accent))]">Next on your schedule</div><div className="mt-5 flex items-end justify-between"><div><div className="text-lg font-extrabold">{summary?.nextClass?.title ?? 'Your next class'}</div><div className="mt-1 text-xs text-white/50">{summary?.nextClass?.room ?? 'Schedule syncing'} · {summary?.nextClass?.time ?? 'Time to be announced'}</div></div><div className="rounded-xl bg-white/10 p-2.5 text-[hsl(var(--accent))]"><GraduationCap size={20} /></div></div><Link href="/campus" data-testid="link-open-schedule" className="mt-5 flex items-center justify-between border-t border-white/10 pt-3 text-[10px] font-bold text-white/50 hover:text-white">View campus pulse <ArrowUpRight size={14} /></Link></div></section><section className="card-lumen rounded-2xl border hairline p-5" data-testid="card-active-communities"><div className="flex items-center justify-between"><div><div className="mono text-[10px] uppercase tracking-[.16em] text-muted-foreground">Your circles</div><div className="mt-1 text-xl font-extrabold">{summary?.activeCommunities ?? '—'} <span className="text-xs font-medium text-muted-foreground">active communities</span></div></div><Users size={18} className="text-[hsl(var(--secondary))]" /></div>{communities.slice(0, 3).map((community) => <Link href="/campus" key={community.id} data-testid={`link-community-${community.id}`} className="mt-4 flex items-center gap-3 hover:opacity-75"><span className="flex h-8 w-8 items-center justify-center rounded-lg bg-[hsl(var(--secondary)/.14)] text-[11px] font-extrabold">{community.name.slice(0, 2).toUpperCase()}</span><span className="min-w-0 flex-1"><span className="block truncate text-xs font-bold">{community.name}</span><span className="block truncate text-[10px] text-muted-foreground">{community.members.toLocaleString()} members</span></span><ChevronRight size={14} className="text-muted-foreground" /></Link>)}{!communities.length && <p className="mt-4 text-xs text-muted-foreground">Your community list will appear here.</p>}<Link href="/campus" data-testid="link-view-communities" className="mt-5 flex items-center justify-between border-t pt-3 text-[11px] font-bold text-muted-foreground hover:text-foreground">Explore communities <ArrowUpRight size={14} /></Link></section><section className="card-lumen rounded-2xl border hairline p-5"><div className="flex items-center gap-2 text-sm font-extrabold"><CalendarDays size={16} className="text-[hsl(var(--primary))]" /> Upcoming on campus</div><p className="mt-3 text-xs leading-5 text-muted-foreground">Browse talks, study groups, and events from your university.</p><Link href="/campus" data-testid="link-upcoming-events" className="mt-4 inline-flex items-center gap-1 text-[11px] font-bold text-[hsl(var(--primary))]">See what’s happening <ArrowUpRight size={13} /></Link></section></aside>;
}

function PageHeading({ eyebrow, title, copy, action }: { eyebrow: string; title: string; copy: string; action?: ReactNode }) {
  return <div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><div className="mono mb-2 text-[10px] font-medium uppercase tracking-[.2em] text-[hsl(var(--primary))]">{eyebrow}</div><h1 className="text-3xl font-extrabold tracking-[-.04em] md:text-5xl">{title}</h1><p className="mt-2 max-w-xl text-sm leading-6 text-muted-foreground">{copy}</p></div>{action}</div>;
}

function HomePage({ profile, summary, posts, postsLoading, postsError, communities, onRetry, onLike, onPublished, onCreate }: any) {
  const displayName = profile?.name?.split(' ')[0] ?? 'there'; const [feedMode, setFeedMode] = useState('Curated');
  return <div className="lumen-rise"><div className="mb-7 flex items-end justify-between gap-4"><div><div className="mono mb-2 text-[10px] uppercase tracking-[.2em] text-muted-foreground">{new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}</div><h1 className="text-3xl font-extrabold tracking-[-.045em] md:text-5xl">{summary?.greeting ?? `Good to see you, ${displayName}.`}</h1><p className="mt-2 text-sm text-muted-foreground">Your global academic campus, in one considered view.</p></div><div className="hidden items-center gap-2 rounded-full border bg-[hsl(var(--card)/.7)] px-3 py-2 text-[10px] font-bold text-muted-foreground lg:flex"><span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent))] lumen-pulse" /> Network live</div></div><div className="grid grid-cols-1 gap-7 xl:grid-cols-[minmax(0,1fr)_300px]"><div className="min-w-0 space-y-5"><Stories profile={profile} /><div className="hidden md:block"><Composer profile={profile} onPublished={onPublished} /></div><button onClick={onCreate} data-testid="button-create-post-mobile" className="flex w-full items-center gap-3 rounded-2xl border bg-[hsl(var(--card))] p-4 text-left text-sm text-muted-foreground shadow-[var(--shadow-sm)] md:hidden"><Avatar name={profile?.name ?? 'You'} image={profile?.avatar} size="sm" /> What are you learning today? <Plus size={17} className="ml-auto text-[hsl(var(--primary))]" /></button><div className="flex items-center justify-between px-1 pt-2"><div className="flex items-center gap-2"><span className="h-2 w-2 rounded-full bg-[hsl(var(--accent))]" /><h2 className="text-sm font-extrabold">From your network</h2></div><button onClick={() => setFeedMode((value) => value === 'Curated' ? 'Latest' : 'Curated')} data-testid="button-feed-filter" className="inline-flex items-center gap-1.5 rounded-lg px-2 py-1 text-[11px] font-bold text-muted-foreground hover:bg-[hsl(var(--muted))]">{feedMode}</button></div>{postsLoading ? <div className="card-lumen rounded-2xl border hairline p-6"><LoadingBlock lines={4} /></div> : postsError ? <QueryError onRetry={onRetry} /> : posts?.length ? posts.map((post: any) => <PostCard key={post.id} post={post} onLike={onLike} />) : <EmptyState icon={MessageCircle} title="Your feed is still quiet" copy="Be the first to share a question, a finding, or a small win with your academic network." />}</div><SummaryRail summary={summary} communities={communities ?? []} /></div></div>;
}

function ExplorePage({ searchValue, setSearchValue, results, loading, error, universities, communities, onRetry }: any) {
  const [filter, setFilter] = useState('all'); const visible = results?.filter((result: any) => filter === 'all' || result.type === filter) ?? [];
  return <div className="lumen-rise"><PageHeading eyebrow="Discovery desk" title="Find your people." copy="Search across institutions, communities, researchers, and conversations worth carrying forward." /><div className="relative mb-8 max-w-2xl"><Search size={19} className="absolute left-4 top-4 text-muted-foreground" /><input autoFocus value={searchValue} onChange={(event) => setSearchValue(event.target.value)} placeholder="Try a university, field, or person" data-testid="input-explore-search" className="h-14 w-full rounded-2xl border bg-[hsl(var(--card))] pl-12 pr-4 text-sm font-semibold outline-none transition focus:border-[hsl(var(--primary))] focus:ring-4 focus:ring-[hsl(var(--primary)/.12)]" /></div><div className="mb-6 flex flex-wrap gap-2">{['all', 'people', 'universities', 'communities', 'posts'].map((item) => <button key={item} onClick={() => setFilter(item)} data-testid={`button-filter-${item}`} className={`rounded-full border px-3.5 py-2 text-[11px] font-bold capitalize transition ${filter === item ? 'border-[hsl(var(--primary))] bg-[hsl(var(--primary))] text-white' : 'text-muted-foreground hover:bg-[hsl(var(--muted))]'}`}>{item}</button>)}</div>{searchValue ? loading ? <div className="max-w-3xl rounded-2xl border bg-[hsl(var(--card))] p-6"><LoadingBlock lines={5} /></div> : error ? <QueryError onRetry={onRetry} /> : <div className="grid max-w-4xl gap-3">{visible.map((result: any) => <div key={result.id} className="card-lumen flex items-center gap-4 rounded-2xl border hairline p-4 transition hover:-translate-y-0.5" data-testid={`result-${result.id}`}><div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--secondary)/.13)]">{result.image ? <img src={result.image} alt="" className="h-full w-full rounded-xl object-cover" /> : result.type === 'universities' ? <Landmark size={18} /> : result.type === 'communities' ? <Users size={18} /> : result.type === 'posts' ? <FileText size={18} /> : <UserRound size={18} />}</div><div className="min-w-0 flex-1"><div className="text-sm font-extrabold">{result.title}</div><div className="mt-1 text-xs text-muted-foreground">{result.subtitle}</div></div><span className="rounded-full bg-[hsl(var(--muted))] px-2 py-1 text-[9px] font-bold uppercase tracking-wider text-muted-foreground">{result.type}</span><ArrowUpRight size={15} className="text-muted-foreground" /></div>)}{!visible.length && <EmptyState icon={Search} title="No matches yet" copy="Try a broader term or search by institution, field, or community." />}</div> : <div className="grid gap-7 lg:grid-cols-[1.2fr_1fr]"><section><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-extrabold">Institutions to know</h2><span className="mono text-[10px] text-muted-foreground">FEATURED</span></div><div className="grid gap-3 sm:grid-cols-2">{universities?.slice(0, 6).map((university: any) => <div key={university.id} className="card-lumen rounded-2xl border hairline p-4 transition hover:-translate-y-0.5 hover:border-[hsl(var(--primary)/.55)]" data-testid={`card-university-${university.id}`}><div className="flex items-start justify-between"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--primary))] text-sm font-extrabold text-white">{university.initials}</span>{university.verified && <BadgeCheck size={15} className="text-[hsl(var(--primary))]" />}</div><h3 className="mt-4 text-sm font-extrabold leading-5">{university.name}</h3><p className="mt-1 text-[11px] text-muted-foreground">{university.city}, {university.country}</p><div className="mt-4 flex items-center justify-between text-[10px] font-bold text-muted-foreground"><span>{university.students.toLocaleString()} students</span><ArrowUpRight size={13} /></div></div>)}</div></section><section><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-extrabold">Active communities</h2><span className="mono text-[10px] text-muted-foreground">RIGHT NOW</span></div><div className="space-y-3">{communities?.slice(0, 5).map((community: any) => <div key={community.id} className="card-lumen flex items-center gap-3 rounded-2xl border hairline p-4" data-testid={`card-community-${community.id}`}><span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--secondary)/.13)] text-xs font-extrabold">{community.name.slice(0, 2).toUpperCase()}</span><span className="min-w-0 flex-1"><span className="block truncate text-sm font-extrabold">{community.name}</span><span className="mt-1 block truncate text-[11px] text-muted-foreground">{community.category} · {community.members.toLocaleString()} members</span></span><ChevronRight size={15} className="text-muted-foreground" /></div>)}</div></section></div>}</div>;
}

function CampusPage({ profile, communities, universities }: any) {
  const current = universities?.find((university: any) => university.name === profile?.university); const [following, setFollowing] = useState(false); const [joined, setJoined] = useState<Record<string, boolean>>({});
  return <div className="lumen-rise"><PageHeading eyebrow="Campus pulse" title={profile?.university ?? 'Your campus'} copy="A shared view of the people, communities, and places that make your academic home." action={<button onClick={() => setFollowing((value) => !value)} data-testid="button-campus-follow" className={`inline-flex items-center gap-2 rounded-xl px-4 py-2.5 text-xs font-extrabold ${following ? 'border bg-[hsl(var(--muted))] text-muted-foreground' : 'bg-[hsl(var(--primary))] text-white'}`}><Plus size={15} /> {following ? 'Following locally' : 'Follow campus'}</button>} /><section className="relative mb-8 overflow-hidden rounded-3xl bg-[hsl(var(--sidebar))] p-6 text-[hsl(var(--sidebar-foreground))] md:p-8"><div className="lumen-grid absolute inset-0 opacity-30" /><div className="relative flex flex-col justify-between gap-7 md:flex-row md:items-end"><div><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-[hsl(var(--primary))] text-xl font-extrabold text-white">{current?.initials ?? profile?.university?.slice(0, 2).toUpperCase() ?? 'LU'}</div><h2 className="mt-6 max-w-xl text-3xl font-extrabold md:text-4xl">{profile?.university ?? 'Find your university community'}</h2><div className="mt-3 flex flex-wrap gap-4 text-xs text-white/55"><span className="inline-flex items-center gap-1.5"><Globe2 size={13} /> {current ? `${current.city}, ${current.country}` : profile?.country ?? 'Global'}</span>{current && <span className="inline-flex items-center gap-1.5"><Users size={13} /> {current.students.toLocaleString()} students</span>}</div></div><div className="flex items-center gap-2 text-xs font-bold text-[hsl(var(--accent))]">Academic activity <ArrowUpRight size={15} /></div></div></section><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-extrabold">Communities at your edge</h2><span className="mono text-[10px] text-muted-foreground">{communities?.length ?? 0} FOUND</span></div>{communities?.length ? <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{communities.map((community: any) => { const isJoined = joined[community.id] ?? community.joined; return <div key={community.id} className="card-lumen rounded-2xl border hairline p-5" data-testid={`campus-community-${community.id}`}><div className="flex items-start justify-between"><span className="rounded-full bg-[hsl(var(--primary)/.13)] px-2 py-1 text-[9px] font-extrabold uppercase tracking-wider">{community.category}</span><button onClick={() => setJoined((items) => ({ ...items, [community.id]: !isJoined }))} data-testid={`button-join-${community.id}`} className={`rounded-lg px-2.5 py-1.5 text-[10px] font-extrabold ${isJoined ? 'bg-[hsl(var(--muted))] text-muted-foreground' : 'bg-[hsl(var(--primary))] text-white'}`}>{isJoined ? <><Check size={12} className="mr-1 inline" /> Joined</> : 'Join locally'}</button></div><h3 className="mt-5 text-base font-extrabold">{community.name}</h3><p className="mt-2 line-clamp-2 text-xs leading-5 text-muted-foreground">{community.description}</p><div className="mt-5 flex items-center justify-between border-t pt-3 text-[10px] font-bold text-muted-foreground"><span>{community.members.toLocaleString()} members</span><span>{community.university}</span></div></div>; })}</div> : <EmptyState icon={Users} title="No campus circles yet" copy="When communities become active on your campus, they will gather here." />}</div>;
}

function ProfilePage({ profile, posts }: any) {
  const ownPosts = posts?.filter((post: any) => post.author?.id === profile?.id) ?? []; const [editing, setEditing] = useState(false);
  return <div className="lumen-rise max-w-4xl"><PageHeading eyebrow="Academic identity" title="Your profile" copy="A clear, credible snapshot of the work and communities you bring to the network." action={<button onClick={() => setEditing((value) => !value)} data-testid="button-edit-profile" className="inline-flex items-center gap-2 rounded-xl border bg-[hsl(var(--card))] px-4 py-2.5 text-xs font-extrabold hover:border-[hsl(var(--primary))]"><Settings size={14} /> {editing ? 'Close preview' : 'Edit profile'}</button>} />{editing && <div className="mb-4 rounded-2xl border border-[hsl(var(--primary)/.28)] bg-[hsl(var(--primary)/.07)] px-4 py-3 text-xs font-semibold text-muted-foreground">Profile editing is a local preview. The current profile hook is read-only, so no changes are being persisted.</div>}<section className="card-lumen overflow-hidden rounded-3xl border hairline"><div className="h-28 bg-[hsl(var(--sidebar))] md:h-36" /><div className="px-5 pb-6 md:px-8"><div className="-mt-10 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><Avatar name={profile?.name ?? 'Academic profile'} image={profile?.avatar} size="xl" verified={profile?.verified} /><span className="w-fit rounded-full bg-[hsl(var(--primary)/.13)] px-3 py-1.5 text-[10px] font-extrabold">{profile?.verified ? 'Verified academic identity' : 'Academic identity'}</span></div><h2 className="mt-5 text-2xl font-extrabold">{profile?.name ?? 'Your name'}</h2><p className="mt-1 text-sm text-muted-foreground">@{profile?.handle ?? 'your-handle'} · {profile?.role ?? 'Student'}</p><div className="mt-5 flex flex-wrap gap-x-5 gap-y-2 text-xs text-muted-foreground"><span className="inline-flex items-center gap-1.5"><GraduationCap size={14} /> {profile?.university ?? 'University'}</span><span className="inline-flex items-center gap-1.5"><Globe2 size={14} /> {profile?.country ?? 'Country'}</span><span className="inline-flex items-center gap-1.5"><Sparkles size={14} /> {profile?.field ?? 'Field of study'}</span></div><div className="mt-7 flex gap-8 border-t pt-5"><div><strong className="block text-lg">{profile?.followers ?? 0}</strong><span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Followers</span></div><div><strong className="block text-lg">{profile?.following ?? 0}</strong><span className="text-[10px] font-bold uppercase tracking-wider text-muted-foreground">Following</span></div></div></div></section><div className="mt-8 flex items-center justify-between"><h2 className="text-sm font-extrabold">Your contributions</h2><span className="mono text-[10px] text-muted-foreground">{ownPosts.length} POSTS</span></div><div className="mt-3 space-y-3">{ownPosts.slice(0, 3).map((post: any) => <PostCard key={post.id} post={post} onLike={() => undefined} />)}{!ownPosts.length && <EmptyState icon={FileText} title="Your work starts here" copy="Publish your first thought from the home feed to build your academic record." action={<Link href="/" data-testid="link-start-post" className="mt-5 inline-flex items-center gap-2 rounded-lg bg-[hsl(var(--primary))] px-3 py-2 text-xs font-extrabold text-white">Share an update <ArrowUpRight size={13} /></Link>} />}</div></div>;
}

function SettingsPage() {
  const [theme, setTheme] = useState<'light' | 'dark' | 'midnight'>(() => (localStorage.getItem('lumen-theme') as 'light' | 'dark' | 'midnight') || 'light');
  useEffect(() => { document.documentElement.classList.toggle('dark', theme !== 'light'); document.documentElement.classList.toggle('midnight', theme === 'midnight'); localStorage.setItem('lumen-theme', theme); }, [theme]);
  return <div className="lumen-rise max-w-3xl"><PageHeading eyebrow="Control room" title="Settings" copy="Tune how LumenUniv looks, feels, and keeps you in the loop." /><div className="space-y-4"><section className="card-lumen rounded-2xl border hairline p-5 md:p-6" data-testid="settings-appearance"><div className="flex items-start gap-4"><div className="rounded-xl bg-[hsl(var(--primary)/.13)] p-2.5 text-[hsl(var(--primary))]"><Sun size={18} /></div><div className="flex-1"><h2 className="text-sm font-extrabold">Appearance</h2><p className="mt-1 text-xs leading-5 text-muted-foreground">Choose the canvas that keeps your attention on the work.</p><div className="mt-5 grid gap-2 sm:grid-cols-3">{(['light', 'dark', 'midnight'] as const).map((item) => <button key={item} onClick={() => setTheme(item)} data-testid={`button-theme-${item}`} className={`flex items-center gap-3 rounded-xl border p-3 text-left text-xs font-bold transition ${theme === item ? 'border-[hsl(var(--primary))] bg-[hsl(var(--primary)/.12)]' : 'hover:bg-[hsl(var(--muted))]'}`}>{item === 'light' ? <Sun size={16} /> : <Moon size={16} />}<span className="capitalize">{item}</span>{theme === item && <CheckCircle2 size={15} className="ml-auto text-[hsl(var(--primary))]" />}</button>)}</div></div></div></section><section className="card-lumen rounded-2xl border hairline p-5 md:p-6"><div className="flex items-start gap-4"><div className="rounded-xl bg-[hsl(var(--secondary)/.13)] p-2.5 text-[hsl(var(--secondary))]"><Bell size={18} /></div><div className="flex-1"><h2 className="text-sm font-extrabold">Notifications</h2><p className="mt-1 text-xs leading-5 text-muted-foreground">Notification preferences are managed by your academic network.</p><div className="mt-5 flex items-center justify-between border-t pt-4 text-xs font-semibold"><span>Network activity</span><span className="rounded-full bg-[hsl(var(--primary)/.13)] px-2.5 py-1 text-[10px] font-bold">On</span></div></div></div></section><section className="card-lumen rounded-2xl border hairline p-5 md:p-6"><div className="flex items-start gap-4"><div className="rounded-xl bg-[hsl(var(--secondary)/.13)] p-2.5 text-[hsl(var(--secondary))]"><ShieldCheck size={18} /></div><div><h2 className="text-sm font-extrabold">Trust and privacy</h2><p className="mt-1 max-w-lg text-xs leading-5 text-muted-foreground">Your academic identity is yours. Profile verification and privacy controls will appear here as your account grows.</p></div></div></section></div></div>;
}

function PreviewMark({ children }: { children: ReactNode }) {
  return <span className="inline-flex items-center gap-1.5 rounded-full border border-[hsl(var(--accent)/.34)] bg-[hsl(var(--accent)/.1)] px-2.5 py-1 text-[9px] font-extrabold uppercase tracking-[.14em] text-[hsl(var(--accent))]"><span className="h-1.5 w-1.5 rounded-full bg-[hsl(var(--accent))]" />{children}</span>;
}

function PreviewPage({ eyebrow, title, copy, icon: Icon, children }: { eyebrow: string; title: string; copy: string; icon: IconType; children: ReactNode }) {
  return <div className="lumen-rise"><PageHeading eyebrow={eyebrow} title={title} copy={copy} action={<PreviewMark>Product preview</PreviewMark>} /><div className="relative overflow-hidden rounded-[1.75rem] border border-[hsl(var(--primary)/.18)] bg-[hsl(var(--card))] p-4 shadow-[var(--shadow-md)] sm:p-6"><div className="pointer-events-none absolute -right-24 -top-28 h-72 w-72 rounded-full bg-[hsl(var(--primary)/.12)] blur-3xl" /><div className="pointer-events-none absolute -bottom-24 left-1/3 h-56 w-56 rounded-full bg-[hsl(var(--accent)/.08)] blur-3xl" /><div className="relative"><div className="mb-6 flex items-center gap-3 border-b pb-4"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--sidebar))] text-[hsl(var(--accent))]"><Icon size={19} /></span><div><div className="text-[10px] font-extrabold uppercase tracking-[.16em] text-muted-foreground">Designed surface</div><div className="mt-0.5 text-sm font-extrabold">Useful now, connected when ready</div></div></div>{children}</div></div></div>;
}

function ShortsPreview() {
  const [saved, setSaved] = useState(false); const [playing, setPlaying] = useState(false);
  return <PreviewPage eyebrow="Short-form learning" title="Ideas in motion." copy="A focused lane for explanations, lab notes, and the moments that make a difficult idea click." icon={PlaySquare}><div className="grid gap-5 lg:grid-cols-[minmax(0,1fr)_320px]"><section className="relative min-h-[440px] overflow-hidden rounded-3xl bg-[hsl(var(--sidebar))] p-6 text-white sm:p-8"><div className="lumen-grid absolute inset-0 opacity-25" /><div className="absolute -right-20 top-10 h-56 w-56 rounded-full bg-[hsl(var(--secondary)/.7)] blur-3xl" /><div className="absolute -bottom-28 left-8 h-64 w-64 rounded-full bg-[hsl(var(--accent)/.28)] blur-3xl" /><div className="relative flex h-full flex-col justify-between"><div className="flex items-center justify-between"><PreviewMark>Preview · no playback yet</PreviewMark><span className="mono text-[10px] text-white/50">01 / 04</span></div><div className="mx-auto flex w-full max-w-[240px] flex-1 flex-col justify-center"><div className="flex aspect-[4/5] flex-col justify-between rounded-[1.5rem] border border-white/15 bg-[linear-gradient(155deg,hsl(246_58%_48%/.8),hsl(232_44%_12%/.94))] p-5 shadow-2xl"><div className="flex items-center justify-between text-[10px] font-bold text-white/60"><span>FIELD NOTE 04</span><Video size={15} /></div><div><div className="mb-3 h-1 w-12 rounded-full bg-[hsl(var(--accent))]" /><h2 className="font-display text-2xl font-bold leading-tight">Why do stars form in clusters?</h2><p className="mt-3 text-xs leading-5 text-white/60">A 48-second visual explanation from the astrophysics circle.</p></div><button onClick={() => setPlaying((value) => !value)} data-testid="button-short-play" className="flex w-fit items-center gap-2 rounded-xl bg-white px-3 py-2 text-[11px] font-extrabold text-[hsl(var(--sidebar))]">{playing ? 'Preview paused' : 'Play preview'} <Play size={13} fill="currentColor" /></button></div></div><div className="mt-5 flex items-center justify-between"><div><p className="text-sm font-extrabold">The orbital notebook</p><p className="mt-1 text-xs text-white/50">Maya Okafor · Astrophysics</p></div><button onClick={() => setSaved((value) => !value)} data-testid="button-save-short" className={`rounded-xl border p-2.5 transition ${saved ? 'border-[hsl(var(--accent))] text-[hsl(var(--accent))]' : 'border-white/15 text-white/65 hover:border-white/40'}`} aria-label={saved ? 'Remove from saved' : 'Save short'}><Bookmark size={16} className={saved ? 'fill-current' : ''} /></button></div></div></section><aside className="space-y-3"><div className="flex items-center justify-between"><h2 className="text-sm font-extrabold">Up next</h2><span className="mono text-[10px] text-muted-foreground">CURATED</span></div>{['A field guide to coral bleaching', 'Three ways to read a primary source', 'The quiet mathematics of music'].map((item, index) => <button key={item} data-testid={`button-short-queue-${index}`} onClick={() => setPlaying(false)} className="card-lumen flex w-full items-center gap-3 rounded-2xl border hairline p-3 text-left transition hover:-translate-y-0.5 hover:border-[hsl(var(--primary)/.5)]"><span className="flex h-16 w-12 shrink-0 items-center justify-center rounded-xl bg-[hsl(var(--secondary))] text-white"><Play size={15} /></span><span className="min-w-0 flex-1"><span className="block text-xs font-extrabold leading-5">{item}</span><span className="mt-1 block text-[10px] text-muted-foreground">{index + 1} min · academic short</span></span><ChevronRight size={15} className="text-muted-foreground" /></button>)}<div className="rounded-2xl border border-dashed border-[hsl(var(--primary)/.28)] bg-[hsl(var(--primary)/.06)] p-4"><div className="flex items-center gap-2 text-xs font-extrabold"><Sparkles size={15} className="text-[hsl(var(--primary))]" />Built for clarity</div><p className="mt-2 text-[11px] leading-5 text-muted-foreground">Shorts are a product preview until video publishing and playback APIs are connected.</p></div></aside></div></PreviewPage>;
}

function ChatPreview() {
  const [active, setActive] = useState('Amina K.'); const [draft, setDraft] = useState(''); const [sent, setSent] = useState<string[]>([]);
  const conversations = [{ name: 'Amina K.', detail: 'Seminar group · 4 members', color: 'bg-[hsl(var(--primary))]' }, { name: 'Materials Lab', detail: 'Community · 18 members', color: 'bg-[hsl(var(--accent))]' }, { name: 'Diego Morales', detail: 'Direct message', color: 'bg-[hsl(var(--secondary))]' }];
  const sendMessage = () => { if (!draft.trim()) return; setSent((items) => [...items, draft.trim()]); setDraft(''); };
  return <PreviewPage eyebrow="Academic dialogue" title="Make room for dialogue." copy="A quieter place for seminars, lab teams, and the conversations that deserve more than a comment thread." icon={MessageCircle}><div className="grid min-h-[510px] overflow-hidden rounded-2xl border hairline md:grid-cols-[240px_1fr]"><aside className="border-b bg-[hsl(var(--muted)/.42)] p-3 md:border-b-0 md:border-r"><div className="mb-3 flex items-center justify-between px-2"><span className="text-xs font-extrabold">Conversations</span><PreviewMark>Preview</PreviewMark></div>{conversations.map((conversation) => <button key={conversation.name} onClick={() => setActive(conversation.name)} data-testid={`button-chat-${conversation.name.replace(/\W/g, '-').toLowerCase()}`} className={`flex w-full items-center gap-3 rounded-xl p-3 text-left transition ${active === conversation.name ? 'bg-[hsl(var(--card))] shadow-[var(--shadow-sm)]' : 'hover:bg-[hsl(var(--card)/.6)]'}`}><span className={`flex h-9 w-9 items-center justify-center rounded-xl text-[10px] font-extrabold text-white ${conversation.color}`}>{conversation.name.slice(0, 2).toUpperCase()}</span><span className="min-w-0"><span className="block truncate text-xs font-extrabold">{conversation.name}</span><span className="mt-1 block truncate text-[10px] text-muted-foreground">{conversation.detail}</span></span></button>)}</aside><section className="flex min-h-[420px] flex-col bg-[hsl(var(--card))]"><div className="flex items-center justify-between border-b p-4"><div><div className="text-sm font-extrabold">{active}</div><div className="mt-1 text-[10px] text-muted-foreground">Preview conversation · persistence not connected</div></div><button data-testid="button-chat-details" onClick={() => setActive(active)} className="rounded-lg p-2 text-muted-foreground hover:bg-[hsl(var(--muted))]" aria-label="Conversation details"><Users size={16} /></button></div><div className="flex-1 space-y-4 p-4"><div className="max-w-[82%] rounded-2xl rounded-tl-md bg-[hsl(var(--muted))] p-3 text-xs leading-5"><p className="font-bold">Amina K.</p><p className="mt-1">Has anyone found a clear source for the methods section?</p><span className="mt-2 block text-[10px] text-muted-foreground">09:42</span></div><div className="ml-auto max-w-[82%] rounded-2xl rounded-tr-md bg-[hsl(var(--primary))] p-3 text-xs leading-5 text-white"><p>Sharing my reading list after the session.</p><span className="mt-2 block text-[10px] text-white/60">09:44</span></div>{sent.map((message, index) => <div key={`${message}-${index}`} className="ml-auto max-w-[82%] rounded-2xl rounded-tr-md bg-[hsl(var(--primary))] p-3 text-xs leading-5 text-white"><p>{message}</p><span className="mt-2 block text-[10px] text-white/60">Just now</span></div>)}</div><div className="border-t p-3"><div className="flex items-center gap-2 rounded-xl border bg-[hsl(var(--background))] p-1.5"><button data-testid="button-chat-attach" onClick={() => setDraft((value) => `${value}${value ? ' ' : ''}[Attachment preview]`)} className="rounded-lg p-2 text-muted-foreground hover:bg-[hsl(var(--muted))]" aria-label="Attach a file"><Paperclip size={15} /></button><input value={draft} onChange={(event) => setDraft(event.target.value)} onKeyDown={(event) => event.key === 'Enter' && sendMessage()} data-testid="input-chat-draft" placeholder="Write a reply…" className="min-w-0 flex-1 bg-transparent px-1 text-xs outline-none" /><button onClick={sendMessage} disabled={!draft.trim()} data-testid="button-chat-send" className="rounded-lg bg-[hsl(var(--primary))] p-2 text-white disabled:opacity-40" aria-label="Send message"><Send size={14} /></button></div></div></section></div></PreviewPage>;
}

function CoursesPreview() {
  const [selected, setSelected] = useState('Neural systems'); const courses = [{ name: 'Neural systems', code: 'BIO-312', progress: 62, next: 'Synaptic plasticity', color: 'bg-[hsl(var(--primary))]' }, { name: 'Urban field methods', code: 'SOC-204', progress: 38, next: 'Observation log 02', color: 'bg-[hsl(var(--accent))]' }, { name: 'Modern African fiction', code: 'LIT-118', progress: 81, next: 'Reading circle', color: 'bg-[hsl(var(--secondary))]' }];
  return <PreviewPage eyebrow="Learning studio" title="Keep learning in focus." copy="A calm academic cockpit for courses, progress, notes, and the next useful thing to do." icon={GraduationCap}><div className="grid gap-5 lg:grid-cols-[1fr_280px]"><section><div className="mb-4 flex items-center justify-between"><div><h2 className="text-sm font-extrabold">Your active courses</h2><p className="mt-1 text-[11px] text-muted-foreground">Progress is a local preview until course APIs are connected.</p></div><button data-testid="button-course-filter" className="rounded-lg border p-2 text-muted-foreground hover:bg-[hsl(var(--muted))]" aria-label="Filter courses"><BookOpen size={15} /></button></div><div className="space-y-3">{courses.map((course) => <button key={course.name} onClick={() => setSelected(course.name)} data-testid={`button-course-${course.code}`} className={`card-lumen w-full rounded-2xl border p-4 text-left transition hover:-translate-y-0.5 ${selected === course.name ? 'border-[hsl(var(--primary)/.65)] ring-2 ring-[hsl(var(--primary)/.1)]' : 'hairline'}`}><div className="flex items-start gap-3"><span className={`h-10 w-1.5 rounded-full ${course.color}`} /><span className="min-w-0 flex-1"><span className="flex items-center justify-between gap-3"><span className="text-sm font-extrabold">{course.name}</span><span className="mono text-[10px] text-muted-foreground">{course.code}</span></span><span className="mt-1 block text-[11px] text-muted-foreground">Next · {course.next}</span><span className="mt-4 block h-1.5 overflow-hidden rounded-full bg-[hsl(var(--muted))]"><span className={`block h-full rounded-full ${course.color}`} style={{ width: `${course.progress}%` }} /></span><span className="mt-2 block text-[10px] font-bold text-muted-foreground">{course.progress}% through this preview track</span></span></div></button>)}</div></section><aside className="space-y-3"><div className="rounded-2xl bg-[hsl(var(--sidebar))] p-5 text-white"><div className="mono text-[10px] uppercase tracking-[.16em] text-[hsl(var(--accent))]">Next study block</div><h3 className="mt-5 text-xl font-extrabold">{selected}</h3><p className="mt-2 text-xs leading-5 text-white/55">Continue with the next unit when your course space is available.</p><button data-testid="button-course-open" onClick={() => setSelected(selected)} className="mt-5 flex w-full items-center justify-between rounded-xl bg-white/10 px-3 py-2.5 text-xs font-bold hover:bg-white/15">Open syllabus preview <ArrowUpRight size={14} /></button></div><Link href="/library" data-testid="link-course-library" className="card-lumen flex items-center gap-3 rounded-2xl border hairline p-4 text-xs font-extrabold hover:border-[hsl(var(--primary)/.45)]"><BookMarked size={17} className="text-[hsl(var(--primary))]" /><span className="flex-1">Browse course reading</span><ChevronRight size={14} className="text-muted-foreground" /></Link></aside></div></PreviewPage>;
}

function CommunitiesPreview({ communities }: { communities: any[] }) {
  const [joined, setJoined] = useState<Record<string, boolean>>({});
  return <PreviewPage eyebrow="Academic circles" title="Find your circle." copy="Explore communities by field, campus, and shared curiosity. Joining below is a local preview until membership APIs are connected." icon={Users}><div className="mb-5 flex items-center justify-between"><div><h2 className="text-sm font-extrabold">Active communities</h2><p className="mt-1 text-[11px] text-muted-foreground">{communities.length ? `${communities.length} circles from the live directory` : 'The directory is quiet right now.'}</p></div><PreviewMark>Live directory</PreviewMark></div>{communities.length ? <div className="grid gap-3 md:grid-cols-2">{communities.map((community) => { const isJoined = joined[community.id] ?? community.joined; return <article key={community.id} className="card-lumen rounded-2xl border hairline p-5" data-testid={`preview-community-${community.id}`}><div className="flex items-start justify-between gap-3"><span className="rounded-full bg-[hsl(var(--primary)/.12)] px-2.5 py-1 text-[9px] font-extrabold uppercase tracking-wider text-[hsl(var(--primary))]">{community.category}</span><button onClick={() => setJoined((items) => ({ ...items, [community.id]: !isJoined }))} data-testid={`button-community-join-${community.id}`} className={`rounded-lg px-3 py-1.5 text-[10px] font-extrabold transition ${isJoined ? 'bg-[hsl(var(--muted))] text-muted-foreground' : 'bg-[hsl(var(--primary))] text-white'}`}>{isJoined ? <><Check size={12} className="mr-1 inline" /> Joined</> : 'Join locally'}</button></div><h3 className="mt-5 text-base font-extrabold">{community.name}</h3><p className="mt-2 line-clamp-2 text-xs leading-5 text-muted-foreground">{community.description}</p><div className="mt-5 flex items-center justify-between border-t pt-3 text-[10px] font-bold text-muted-foreground"><span>{community.members.toLocaleString()} members</span><span>{community.university}</span></div></article>; })}</div> : <EmptyState icon={Users} title="No circles surfaced" copy="The live community directory has not returned any active spaces yet." />}</PreviewPage>;
}

function LibraryPreview() {
  const [query, setQuery] = useState(''); const [saved, setSaved] = useState<Record<string, boolean>>({}); const [filter, setFilter] = useState('All');
  const readings = [{ id: 'r1', kind: 'Paper', title: 'The shape of a useful question', meta: 'Research methods · 12 min', accent: 'bg-[hsl(var(--primary))]' }, { id: 'r2', kind: 'Course note', title: 'A field guide to observation', meta: 'Urban field methods · 8 min', accent: 'bg-[hsl(var(--accent))]' }, { id: 'r3', kind: 'Essay', title: 'Listening as a research practice', meta: 'Cultural studies · 17 min', accent: 'bg-[hsl(var(--secondary))]' }, { id: 'r4', kind: 'Paper', title: 'Networks of care in the city', meta: 'Sociology · 21 min', accent: 'bg-[hsl(var(--primary))]' }];
  const visible = readings.filter((item) => `${item.title} ${item.kind} ${item.meta}`.toLowerCase().includes(query.toLowerCase()) && (filter === 'All' || item.kind === filter));
  return <PreviewPage eyebrow="Reading room" title="A better reading list." copy="Keep papers, course notes, and recommendations close without pretending this surface is persisted yet." icon={LibraryBig}><div className="mb-5 flex flex-col gap-3 sm:flex-row"><div className="relative flex-1"><Search size={15} className="absolute left-3 top-3 text-muted-foreground" /><input value={query} onChange={(event) => setQuery(event.target.value)} data-testid="input-library-search" placeholder="Search your preview library" className="h-10 w-full rounded-xl border bg-[hsl(var(--background))] pl-9 pr-3 text-xs outline-none focus:border-[hsl(var(--primary))]" /></div><div className="flex gap-1.5">{['All', 'Paper', 'Course note'].map((item) => <button key={item} onClick={() => setFilter(item)} data-testid={`button-library-filter-${item.replace(' ', '-').toLowerCase()}`} className={`rounded-xl border px-3 text-[10px] font-bold ${filter === item ? 'border-[hsl(var(--primary))] bg-[hsl(var(--primary))] text-white' : 'text-muted-foreground hover:bg-[hsl(var(--muted))]'}`}>{item}</button>)}</div></div><div className="grid gap-3 md:grid-cols-2">{visible.map((item) => <article key={item.id} className="card-lumen flex gap-3 rounded-2xl border hairline p-4"><span className={`mt-1 h-11 w-1.5 shrink-0 rounded-full ${item.accent}`} /><div className="min-w-0 flex-1"><div className="flex items-center justify-between gap-2"><span className="mono text-[9px] uppercase tracking-[.14em] text-muted-foreground">{item.kind}</span><button onClick={() => setSaved((items) => ({ ...items, [item.id]: !items[item.id] }))} data-testid={`button-library-save-${item.id}`} className={`rounded-lg p-1.5 ${saved[item.id] ? 'text-[hsl(var(--primary))]' : 'text-muted-foreground hover:bg-[hsl(var(--muted))]'}`} aria-label={saved[item.id] ? 'Remove saved item' : 'Save item'}><Bookmark size={15} className={saved[item.id] ? 'fill-current' : ''} /></button></div><h3 className="mt-2 text-sm font-extrabold leading-5">{item.title}</h3><p className="mt-1 text-[11px] text-muted-foreground">{item.meta}</p><button onClick={() => setSaved((items) => ({ ...items, [item.id]: true }))} data-testid={`button-library-open-${item.id}`} className="mt-4 inline-flex items-center gap-1 text-[10px] font-extrabold text-[hsl(var(--primary))]">Open reading preview <ArrowUpRight size={12} /></button></div></article>)}</div>{!visible.length && <div className="mt-3"><EmptyState icon={FileSearch} title="Nothing in this view" copy="Try another term or clear the filter. These are curated preview records, not saved backend items." /></div>}</PreviewPage>;
}

function EventsPreview() {
  const [rsvps, setRsvps] = useState<Record<string, boolean>>({}); const events = [{ id: 'e1', date: '18', month: 'MAY', title: 'Open lab: mapping coastal change', place: 'Virtual · Global Climate Circle', time: '16:00 UTC' }, { id: 'e2', date: '21', month: 'MAY', title: 'Research stories from Nairobi', place: 'Lumen Hall · University network', time: '18:30 EAT' }, { id: 'e3', date: '27', month: 'MAY', title: 'Quiet writing session', place: 'Library room 02 · Focus group', time: '09:00 CET' }];
  return <PreviewPage eyebrow="Campus calendar" title="What is happening next." copy="A shared rhythm for lectures, study groups, talks, and the small events that make a campus feel global." icon={CalendarDays}><div className="mb-5 flex items-center justify-between"><div><h2 className="text-sm font-extrabold">Upcoming events</h2><p className="mt-1 text-[11px] text-muted-foreground">RSVPs below are local preview state. Event APIs are not connected.</p></div><button data-testid="button-events-filter" onClick={() => setRsvps({})} className="inline-flex items-center gap-2 rounded-xl border px-3 py-2 text-[10px] font-extrabold text-muted-foreground hover:bg-[hsl(var(--muted))]"><Clock3 size={14} /> Reset preview</button></div><div className="space-y-3">{events.map((event) => <article key={event.id} className="card-lumen flex flex-col gap-4 rounded-2xl border hairline p-4 sm:flex-row sm:items-center"><div className="flex h-16 w-16 shrink-0 flex-col items-center justify-center rounded-2xl bg-[hsl(var(--sidebar))] text-white"><span className="mono text-[9px] text-[hsl(var(--accent))]">{event.month}</span><span className="font-display text-2xl font-bold leading-6">{event.date}</span></div><div className="min-w-0 flex-1"><div className="flex items-center gap-2 text-[10px] font-bold text-[hsl(var(--primary))]"><MapPin size={12} /> {event.time}</div><h3 className="mt-1 text-sm font-extrabold">{event.title}</h3><p className="mt-1 text-[11px] text-muted-foreground">{event.place}</p></div><button onClick={() => setRsvps((items) => ({ ...items, [event.id]: !items[event.id] }))} data-testid={`button-event-rsvp-${event.id}`} className={`rounded-xl px-3 py-2 text-[10px] font-extrabold transition ${rsvps[event.id] ? 'bg-[hsl(var(--accent)/.14)] text-[hsl(var(--accent-foreground))]' : 'border bg-[hsl(var(--card))] hover:border-[hsl(var(--primary))]'}`}>{rsvps[event.id] ? 'RSVP saved locally' : 'Preview RSVP'}</button></article>)}</div></PreviewPage>;
}

function AiPreview() {
  const [prompt, setPrompt] = useState(''); const [answer, setAnswer] = useState('');
  const ask = (value = prompt) => { if (!value.trim()) return; setPrompt(value); setAnswer(`A useful starting point for “${value.trim()}” is to define the question, name the evidence you trust, and decide what would change your mind. This response is a product preview; Lumen AI is not connected to a model yet.`); };
  return <PreviewPage eyebrow="Study companion" title="Study with a little more light." copy="A transparent assistant surface for explaining, summarizing, and planning — with its preview status visible at every step." icon={Sparkles}><div className="grid gap-5 lg:grid-cols-[1fr_300px]"><section className="rounded-2xl border hairline bg-[hsl(var(--background))] p-4 sm:p-6"><div className="mb-6 flex items-center justify-between"><div className="flex items-center gap-3"><span className="flex h-10 w-10 items-center justify-center rounded-xl bg-[hsl(var(--sidebar))] text-[hsl(var(--accent))]"><Bot size={19} /></span><div><h2 className="text-sm font-extrabold">Lumen AI desk</h2><p className="mt-1 text-[10px] text-muted-foreground">Preview mode · no model request sent</p></div></div><PreviewMark>Honest preview</PreviewMark></div>{answer ? <div className="mb-5 rounded-2xl bg-[hsl(var(--card))] p-4 text-sm leading-7 shadow-[var(--shadow-sm)]"><div className="mb-2 flex items-center gap-2 text-[10px] font-extrabold uppercase tracking-[.14em] text-[hsl(var(--primary))]"><Sparkles size={13} /> Starting point</div>{answer}</div> : <div className="mb-5 flex min-h-32 items-center justify-center rounded-2xl border border-dashed border-[hsl(var(--primary)/.25)] p-5 text-center text-xs leading-5 text-muted-foreground">Ask for a concept breakdown, a study plan, or a sharper research question.</div>}<div className="rounded-2xl border bg-[hsl(var(--card))] p-2"><textarea value={prompt} onChange={(event) => setPrompt(event.target.value)} data-testid="input-ai-prompt" rows={3} placeholder="What would you like to understand?" className="w-full resize-none bg-transparent p-2 text-sm leading-6 outline-none placeholder:text-muted-foreground" /><div className="flex items-center justify-between border-t pt-2"><span className="text-[10px] text-muted-foreground">Your prompt stays in this preview.</span><button onClick={() => ask()} disabled={!prompt.trim()} data-testid="button-ai-ask" className="inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-3 py-2 text-[10px] font-extrabold text-white disabled:opacity-40">Ask Lumen <Send size={13} /></button></div></div></section><aside><div className="mb-3 flex items-center justify-between"><h2 className="text-sm font-extrabold">Good starting points</h2><Sparkles size={15} className="text-[hsl(var(--primary))]" /></div><div className="space-y-2">{['Explain a difficult idea simply', 'Turn notes into a study plan', 'Make this question more precise'].map((suggestion, index) => <button key={suggestion} onClick={() => ask(suggestion)} data-testid={`button-ai-suggestion-${index}`} className="card-lumen flex w-full items-center justify-between rounded-xl border hairline p-3 text-left text-xs font-bold hover:border-[hsl(var(--primary)/.5)]"><span>{suggestion}</span><ArrowUpRight size={14} className="text-muted-foreground" /></button>)}</div><div className="mt-4 rounded-2xl border border-dashed border-[hsl(var(--accent)/.38)] bg-[hsl(var(--accent)/.06)] p-4"><div className="text-[10px] font-extrabold uppercase tracking-[.14em] text-[hsl(var(--accent-foreground))]">Why this label?</div><p className="mt-2 text-[11px] leading-5 text-muted-foreground">No external model, answer, or personal memory is being claimed here. The surface is ready for a real AI hook later.</p></div></aside></div></PreviewPage>;
}

function formatWhen(date: string) { const parsed = new Date(date); if (Number.isNaN(parsed.getTime())) return 'Recently'; const minutes = Math.floor((Date.now() - parsed.getTime()) / 60000); if (minutes < 1) return 'Just now'; if (minutes < 60) return `${minutes}m`; const hours = Math.floor(minutes / 60); if (hours < 24) return `${hours}h`; return `${Math.floor(hours / 24)}d`; }

function AppShell({ children, profile, searchValue, setSearchValue, onCreate }: { children: ReactNode; profile: any; searchValue: string; setSearchValue: (value: string) => void; onCreate: () => void }) {
  const [location] = useLocation(); const [menuOpen, setMenuOpen] = useState(false);
  return <div className="min-h-[100dvh] bg-background text-foreground"><div className="fixed inset-y-0 left-0 z-40 hidden md:flex"><Sidebar profile={profile} location={location} /></div>{menuOpen && <div className="fixed inset-0 z-40 flex md:hidden"><div className="absolute inset-0 bg-[hsl(var(--foreground)/.28)] backdrop-blur-sm" onClick={() => setMenuOpen(false)} /><Sidebar profile={profile} location={location} onClose={() => setMenuOpen(false)} /></div>}<div className="md:pl-[252px]"><Topbar profile={profile} searchValue={searchValue} setSearchValue={setSearchValue} onMenu={() => setMenuOpen(true)} /><main className="mx-auto max-w-[1480px] px-4 py-6 pb-24 md:px-8 md:py-9 md:pb-9">{children}</main></div><MobileNav onCreate={onCreate} /></div>;
}

function RoutedErrorBoundary({ children }: { children: ReactNode }) { const [location] = useLocation(); return <ErrorBoundary resetKey={location}>{children}</ErrorBoundary>; }

function Workspace() {
  const [searchValue, setSearchValue] = useState(''); const [publishedNotice, setPublishedNotice] = useState(false); const [createOpen, setCreateOpen] = useState(false);
  const profileQuery = useGetCurrentProfile(); const summaryQuery = useGetDashboardSummary(); const feedQuery = useListFeedPosts({ limit: 20 }); const universitiesQuery = useListUniversities({ limit: 12 }); const communitiesQuery = useListCommunities(); const searchQuery = useSearchAcademic({ q: searchValue || 'academic' }, { query: { enabled: searchValue.trim().length > 0, queryKey: getSearchAcademicQueryKey({ q: searchValue || 'academic' }) } }); const healthQuery = useHealthCheck(); const likeMutation = useTogglePostLike(); const client = useQueryClient();
  const profile = profileQuery.data; const posts = feedQuery.data ?? []; const communities = communitiesQuery.data ?? []; const universities = universitiesQuery.data ?? [];
  const handleLike = (id: string) => likeMutation.mutate({ id }, { onSuccess: () => client.invalidateQueries({ queryKey: getListFeedPostsQueryKey() }) });
  useEffect(() => { if (!publishedNotice) return; const timer = window.setTimeout(() => setPublishedNotice(false), 2800); return () => window.clearTimeout(timer); }, [publishedNotice]);
  const shared = { profile, summary: summaryQuery.data, posts, communities, universities };
  return <AppShell profile={profile} searchValue={searchValue} setSearchValue={setSearchValue} onCreate={() => setCreateOpen(true)}><div className="relative">{publishedNotice && <div className="fixed right-5 top-20 z-30 flex items-center gap-2 rounded-xl border bg-[hsl(var(--card))] px-4 py-3 text-xs font-bold shadow-xl lumen-rise" data-testid="status-published"><CheckCircle2 size={16} className="text-[hsl(var(--primary))]" /> Published to your network</div>}<Switch><Route path="/" component={() => <HomePage {...shared} postsLoading={feedQuery.isLoading} postsError={feedQuery.isError} onRetry={() => feedQuery.refetch()} onLike={handleLike} onPublished={() => setPublishedNotice(true)} onCreate={() => setCreateOpen(true)} />} /><Route path="/home" component={() => <HomePage {...shared} postsLoading={feedQuery.isLoading} postsError={feedQuery.isError} onRetry={() => feedQuery.refetch()} onLike={handleLike} onPublished={() => setPublishedNotice(true)} onCreate={() => setCreateOpen(true)} />} /><Route path="/explore" component={() => <ExplorePage searchValue={searchValue} setSearchValue={setSearchValue} results={searchQuery.data} loading={searchQuery.isLoading} error={searchQuery.isError} universities={universities} communities={communities} onRetry={() => searchQuery.refetch()} />} /><Route path="/shorts" component={ShortsPreview} /><Route path="/campus" component={() => <CampusPage {...shared} />} /><Route path="/courses" component={CoursesPreview} /><Route path="/communities" component={() => <CommunitiesPreview communities={communities} />} /><Route path="/events" component={EventsPreview} /><Route path="/library" component={LibraryPreview} /><Route path="/chat" component={ChatPreview} /><Route path="/messages" component={ChatPreview} /><Route path="/notifications" component={() => <PreviewPage eyebrow="Network signals" title="Stay close to what matters." copy="A focused notification stream for replies, likes, and campus updates. This is a preview because no notification hook exists yet." icon={Bell}><EmptyState icon={Bell} title="Your signal stream is ready" copy="Notifications will appear here once the network notification service is connected." action={<Link href="/" data-testid="link-notifications-home" className="mt-5 inline-flex items-center gap-2 rounded-xl bg-[hsl(var(--primary))] px-3 py-2 text-xs font-extrabold text-white">Return to feed <ArrowUpRight size={13} /></Link>} /></PreviewPage>} /><Route path="/ai" component={AiPreview} /><Route path="/profile" component={() => <ProfilePage {...shared} />} /><Route path="/settings" component={SettingsPage} /><Route component={NotFound} /></Switch></div><div className="mt-12 flex items-center justify-between border-t pt-5 text-[10px] text-muted-foreground"><span className="mono">LUMENUNIV / ACADEMIC HOME BASE</span><span className="hidden items-center gap-1.5 sm:flex"><span className={`h-1.5 w-1.5 rounded-full ${healthQuery.isError ? 'bg-[hsl(var(--destructive))]' : 'bg-[hsl(var(--primary))]'}`} /> {healthQuery.isError ? 'Network degraded' : 'Network operational'}</span></div><CreateSheet open={createOpen} onClose={() => setCreateOpen(false)} profile={profile} onPublished={() => setPublishedNotice(true)} /></AppShell>;
}

function App() {
  return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><RoutedErrorBoundary><Workspace /></RoutedErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>;
}

export default App;